# The glyphs icon theme: the PNGs rendered in the repository, its index (names it
# lacks come from flat-color) and a link per alias (run by bmds-dist).
"$ROOT/tools/install-icon-theme" "$SRC" "$DESTDIR/share/icons/glyphs" "$PKGDIR/aliases" \
        "Glyphs" "gorango's Glyphs, core, coloured" flat-color
